  let l = normalize(vec3f(0.0, 10.0, 5.0));
  let lightNormDot = dot(n, l);
  let ambient = in.vClr.rgb * 0.35;
  let diffuse = max(lightNormDot, 0.0) * in.vClr.rgb * 0.5;
